// §19 WF01 — รับ Lead จากทุกช่องทาง → รูปแบบเดียวกับ POST /api/lead/register
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const s = (v, max) => (v === null || v === undefined) ? '' : String(v).trim().slice(0, max);
const CH = { website: 'website_lead_box', web: 'website_lead_box', facebook: 'facebook_lead_ads', fb: 'facebook_lead_ads',
  line: 'line_oa', linetv: 'line_oa', tiktok: 'tiktok', tt: 'tiktok', ig: 'instagram', instagram: 'instagram',
  phone: 'phone_call', call: 'phone_call', manual: 'manual_entry', agent: 'agent_referral', referral: 'agent_referral' };
const rawChannel = (s(body.channel || body.source || (body.utm && body.utm.source) || 'website', 40) || 'website').toLowerCase();
const channel = CH[rawChannel] || rawChannel;
let interests = [];
if (Array.isArray(body.interests)) interests = body.interests.map(x => s(x, 60)).filter(Boolean);
else if (typeof body.interests === 'string') interests = body.interests.split(/[,;|]/).map(x => x.trim()).filter(Boolean);
if (!interests.length && typeof body.interest === 'string') interests = [s(body.interest, 60)];
const c = (body.consent && typeof body.consent === 'object') ? body.consent : {};
const pdpa = c.pdpa === true || body.pdpaConsent === true || body.consent === true;
const marketing = c.marketing === true || body.marketingConsent === true;
const payload = {
  fullName: s(body.fullName || body.name || ((s(body.firstName,60) + ' ' + s(body.lastName,60)).trim()), 120),
  phone: s(body.phone || body.tel, 30),
  email: s(body.email, 120).toLowerCase(),
  nickname: s(body.nickname, 60) || undefined,
  province: s(body.province, 60) || undefined,
  occupation: s(body.occupation, 80) || undefined,
  ageRange: s(body.ageRange || body.age_range, 20) || undefined,
  lineId: s(body.lineId || body.line_id, 60) || undefined,
  interests: interests.slice(0, 8),
  callbackRequested: !!(body.callbackRequested || body.callback_requested || body.callback),
  consent: { pdpa: pdpa, marketing: marketing, version: s(c.version || body.consentVersion, 12) || '1.0' },
  visitorId: s(body.visitorId || body.visitor_id, 64) || undefined,
  source: channel,
  ref: s(body.ref || body.referralCode, 40) || undefined,
  utm: (body.utm && typeof body.utm === 'object') ? body.utm : { source: rawChannel, campaign: s(body.campaign, 80) || undefined },
};
const missing = [];
if (!payload.fullName) missing.push('fullName');
if (!payload.phone && !payload.email) missing.push('phone หรือ email');
return [{ json: { channel, payload, missing, pdpa, receivedAt: new Date().toISOString(),
  intakeOk: missing.length === 0 && pdpa } }];

// สรุปผลจาก /api/lead/register → ใช้ตัดสินว่าจะแจ้งเตือน/สร้างงานอย่างไร
const reg = $json || {};
const src = $('แปลงข้อมูล Lead + ตรวจ PDPA').first().json;
const lead = reg.lead || {};
const score = Number(lead.score || 0);
return [{ json: {
  ok: reg.ok === true,
  existing: reg.existing === true,
  prospectId: lead.prospectId || lead.id || null,
  name: lead.name || src.payload.fullName,
  phone: src.payload.phone || null,
  email: src.payload.email || null,
  channel: src.channel,
  interests: src.payload.interests || [],
  callbackRequested: src.payload.callbackRequested,
  score: score,
  level: lead.level || 'LOW',
  hot: score >= 70,
  preferredChannel: reg.preferredChannel || null,
  consent: reg.consent || src.payload.consent,
  topics: reg.topics || [],
  error: reg.error || null,
  message: reg.message || '',
} }];
